const server = http.createServer(async (req, res) => {
  let url;
  try {
    url = new URL(req.url, `http://${req.headers.host ?? 'localhost'}`);
  } catch {
    return json(res, 400, { error: 'bad request line' });
  }

  if (url.pathname === '/api/stream') {
    res.writeHead(200, {
      'content-type': 'text/event-stream',
      'cache-control': 'no-cache',
      connection: 'keep-alive',
    });
    res.write(`data: ${JSON.stringify(snapshot())}\n\n`);
    subscribers.add(res);
    // Without this the set grows for the life of the process.
    const drop = () => subscribers.delete(res);
    req.on('close', drop);
    req.on('error', drop);
    return;
  }

  if (req.method === 'POST' && url.pathname === '/api/words') {
    const clientId = String(req.headers['x-forwarded-for'] ?? req.socket.remoteAddress ?? 'unknown');
    if (rateLimited(clientId)) {
      return json(res, 429, { error: 'slow down — too many words too quickly' });
    }

    let payload;
    try {
      payload = JSON.parse(await readBody(req));
    } catch (err) {
      return json(res, 400, { error: `body must be valid JSON (${err.message})` });
    }

    try {
      const word = submit(payload?.word, clientId);
      broadcast();
      return json(res, 201, { word });
    } catch (err) {
      return json(res, 400, { error: err.message });
    }
  }

  if (url.pathname === '/api/words') return json(res, 200, snapshot());
  if (url.pathname === '/health') return json(res, 200, { ok: true });

  if (req.method === 'POST' && url.pathname === '/api/reset') {
    reset();
    broadcast();
    return json(res, 200, { ok: true });
  }

  if (url.pathname !== '/') return json(res, 404, { error: `no such path: ${url.pathname}` });

  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
  res.end(PAGE);
});

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  server.listen(port, () => console.log(`listening on ${port}`));
}

export { server, subscribers };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalise, submit, ranked, total, uniqueWords, weighted, snapshot, reset } from './store.js';

test('counts a word and returns the normalised form', () => {
  reset();
  assert.equal(submit('Agents'), 'agents');
  assert.equal(total(), 1);
});

test('normalising folds case, spacing and punctuation into one word', () => {
  reset();
  submit('Agents');
  submit('  AGENTS ');
  submit('agents!');
  assert.equal(uniqueWords(), 1, 'these are all the same word');
  assert.equal(ranked()[0].count, 3);
});

test('rejects input that is not a usable word', () => {
  reset();
  assert.throws(() => submit(''), /not be empty/);
  assert.throws(() => submit('   '), /not be empty/);
  assert.throws(() => submit(null), /must be a string/);
  assert.throws(() => submit(42), /must be a string/);
  assert.throws(() => submit('x'.repeat(50)), /at most/);
  assert.throws(() => submit('!!!'), /letters or digits/);
});

test('markup cannot survive normalisation', () => {
  reset();
  // The renderer never builds HTML from these, but defence in depth: whatever
  // comes out of here must not be able to carry a tag.
  for (const attack of ['<b>hi</b>', '<script>x</script>', '"><img src=x>']) {
    let out = null;
    try {
      out = submit(attack);
    } catch {
      continue; // rejected outright is also fine
    }
    assert.doesNotMatch(out, /[<>"'`=/]/, `"${attack}" produced "${out}"`);
  }
});

test('keeps letters, digits, hyphens and apostrophes', () => {
  assert.equal(normalise("Don't"), "don't");
  assert.equal(normalise('well-known'), 'well-known');
  assert.equal(normalise('claude5'), 'claude5');
});

test('ranks most-said first, breaking ties alphabetically', () => {
  reset();
  submit('swarm');
  submit('swarm');
  submit('zebra');
  submit('agents');
  const list = ranked();
  assert.equal(list[0].word, 'swarm');
  assert.equal(list[1].word, 'agents', 'equal counts sort alphabetically');
  assert.equal(list[2].word, 'zebra');
});

test('weights scale against the most-said word', () => {
  reset();
  for (let i = 0; i < 10; i++) submit('loud');
  submit('quiet');
  const [first, second] = weighted();
  assert.equal(first.weight, 1);
  assert.ok(second.weight < 0.2 && second.weight > 0);
});

test('a burst of submissions loses none of them', () => {
  reset();
  for (let i = 0; i < 500; i++) submit('spam');
  assert.equal(total(), 500);
  assert.equal(ranked()[0].count, 500);
});

test('the cloud is bounded and says so rather than growing for ever', () => {
  reset();
  for (let i = 0; i < 300; i++) submit(`word${i}`);
  assert.equal(uniqueWords(), 300);
  assert.throws(() => submit('onetoomany'), /full/);
  // An existing word is still countable once the cloud is full.
  assert.equal(submit('word0'), 'word0');
});

test('snapshot is what the page renders', () => {
  reset();
  submit('agents');
  const snap = snapshot();
  assert.equal(snap.total, 1);
  assert.equal(snap.unique, 1);
  assert.deepEqual(Object.keys(snap.words[0]).sort(), ['count', 'weight', 'word']);
});

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { server, subscribers } from './server.js';
import { reset } from './store.js';

let base;

before(async () => {
  await new Promise((r) => server.listen(0, r));
  base = `http://localhost:${server.address().port}`;
});

after(() => server.close());

const say = (word) =>
  fetch(`${base}/api/words`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ word }),
  });

const clear = async () => {
  reset();
  await fetch(`${base}/api/reset`, { method: 'POST' });
};

test('accepts a word and reports it in the snapshot', async () => {
  await clear();
  const res = await say('agents');
  assert.equal(res.status, 201);
  assert.equal((await res.json()).word, 'agents');

  const snap = await (await fetch(`${base}/api/words`)).json();
  assert.equal(snap.total, 1);
  assert.equal(snap.words[0].word, 'agents');
});

test('serves a page that renders text, never markup', async () => {
  const body = await (await fetch(`${base}/`)).text();
  assert.match(body, /Live word cloud/);
  assert.match(body, /EventSource/, 'the page must subscribe to updates');
  assert.match(body, /textContent/, 'words must be set as text');
  // Match the sink, not the word: a comment saying "never innerHTML" is not a
  // vulnerability, and a test that cannot tell the difference is noise.
  assert.doesNotMatch(body, /\.innerHTML\s*=/, 'nothing may assign submitted words into HTML');
  assert.doesNotMatch(body, /insertAdjacentHTML|document\.write/, 'no other HTML sink either');
});

test('a submitted tag cannot reach the page as markup', async () => {
  await clear();
  await say('<img src=x onerror=alert(1)>');
  const snap = await (await fetch(`${base}/api/words`)).json();
  for (const entry of snap.words) {
    assert.doesNotMatch(entry.word, /[<>]/, `stored word "${entry.word}" still carries a tag`);
  }
});

test('rejects unusable input with 400, not 500', async () => {
  assert.equal((await say('')).status, 400);
  assert.equal((await say('!!!')).status, 400);
  assert.equal((await say(null)).status, 400);
  assert.equal((await say('x'.repeat(80))).status, 400);
});

test('rejects a malformed body with 400', async () => {
  const res = await fetch(`${base}/api/words`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: '{oh no',
  });
  assert.equal(res.status, 400);
});

test('rate limits one client hammering the endpoint', async () => {
  await clear();
  let limited = 0;
  for (let i = 0; i < 25; i++) {
    if ((await say('flood')).status === 429) limited += 1;
  }
  assert.ok(limited > 0, 'a single client must not be able to submit without limit');
});

test('the stream sends a snapshot and is cleaned up on disconnect', async () => {
  const before = subscribers.size;
  const controller = new AbortController();
  const res = await fetch(`${base}/api/stream`, { signal: controller.signal });
  const reader = res.body.getReader();
  const first = new TextDecoder().decode((await reader.read()).value);
  assert.match(first, /^data: /);
  assert.equal(subscribers.size, before + 1);

  controller.abort();
  await new Promise((r) => setTimeout(r, 150));
  assert.equal(subscribers.size, before, 'a disconnected client must not be retained');
});

